use super::*;
use semio_framework_actor::typed_operation_page::{TypedOperationResultLane,TYPED_OPERATION_RESULT_PAGE_BYTES};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../🧪️.json")).unwrap()}
fn original()->RetainedCloneGrant{let fixture=fixture();let g=&fixture["receiverGrant"];RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize}}
fn receipt(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation,g:RetainedCloneGrant){assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn prepared(length:usize)->(NativeResultPages,Vec<TypedOperationResultPage>){let g=original();let mut pages=NativeResultPages::new();let mut producers=Vec::new();for (index,slot)in pages.slots.iter_mut().enumerate(){let token=TypedOperationResultToken{receiver:7,operation:u64::MAX-index as u64,generation:u64::MAX,sequence:0,attempt:1};let mut producer=TypedOperationResultPage::from_original(token,TypedOperationResultLane::Diagnostic,vec![81;TYPED_OPERATION_RESULT_PAGE_BYTES],length);assert!(producer.present(g).unwrap().0.is_none());slot.page=producer.present(g).unwrap().0;assert_eq!(slot.page.as_ref().unwrap().bytes().as_ptr(),producer.bytes().as_ptr());producers.push(producer);}assert_eq!(pages.slots.iter().filter(|s|!s.empty()).count(),fixture()["maximumPages"].as_u64().unwrap()as usize);(pages,producers)}
fn close_producers(producers:&mut[TypedOperationResultPage],g:RetainedCloneGrant){for producer in producers{for _ in 0..1000{if producer.terminal_is_empty(){break}let(step,heap)=observe(||producer.close_step(g).unwrap());receipt(step.progress(),heap,g);}assert!(producer.terminal_is_empty());}}
fn close_pages(pages:&mut NativeResultPages,g:RetainedCloneGrant){for _ in 0..1000{if pages.terminal_is_empty(){return}let(p,heap)=observe(||pages.close_step(g).unwrap());receipt(p,heap,g);assert_ne!(p,RetainedCloneProgress::default());}panic!("original Reactor page cancellation stalled");}
fn retire_effects(effects:Vec<Effect>,g:RetainedCloneGrant){let mut owner=ControlledRetirement::new(effects).unwrap_or_else(|_|panic!("typed effects declare controlled retirement"));for _ in 0..1000{if owner.terminal_is_empty(){return}let(step,heap)=observe(||owner.step(g).unwrap());receipt(step.progress(),heap,g);}panic!("original renderer destination retirement stalled");}

/// 🎫️ Eight original loans use the same recipient for bounded receiving and effect publication in each issued turn.
#[test]
fn native_page_batch_preserves_eight_original_loans_through_funded_receiving(){let g=original();for row in fixture()["pageLengths"].as_array().unwrap(){let length=row.as_u64().unwrap()as usize;let(mut pages,mut producers)=prepared(length);let mut effects=Vec::new();let mut turns=0;let mut widest=0;while !pages.terminal_is_empty(){let mut sequence=0;let mut p=RetainedCloneProgress::default();let mut cx=semio_framework_job::StepContext::new(semio_framework_job::OperationId(7),semio_framework_job::Generation(1),semio_framework_job::StepBudget::new(100,u64::MAX,g),semio_framework_job::CancelToken::root_now(),semio_framework_job::logical_now_us,&mut sequence,&mut p);let before=effects.len();for slot in &mut pages.slots{for _ in 0..100{if slot.empty(){break}let grant=cx.retained_grant();let(result,heap)=observe(||{if slot.ready(){let (published,p)=publish(slot,7,&mut effects,64,&cx).unwrap();if published{effects.push(slot.publication.take().unwrap())}p}else{slot.advance(grant).unwrap()}});receipt(result,heap,grant);cx.consume_retained(result).unwrap();if result==RetainedCloneProgress::default(){break}}}widest=widest.max(effects.len()-before);turns+=1;assert!(turns<1000);}assert_eq!(effects.len(),8);for (index,effect)in effects.iter().enumerate(){let Effect::SendMessage{target:MessageEndpoint::Shell{instance},payload}=effect else{panic!("actual receiving must produce typed shell delivery")};assert_eq!(instance.0,"7");let header=TypedOperationResultPage::RENDERER_PAGE_MAGIC.len();assert_eq!(&payload[..header],TypedOperationResultPage::RENDERER_PAGE_MAGIC);assert_eq!(u64::from_le_bytes(payload[header+4..header+12].try_into().unwrap()),u64::MAX-index as u64);assert_eq!(u64::from_le_bytes(payload[header+12..header+20].try_into().unwrap()),u64::MAX);assert_eq!(payload.len(),header+30+length);assert!(payload[header+30..].iter().all(|byte|*byte==81));}close_producers(&mut producers,g);retire_effects(effects,g);let(_,heap)=observe(||drop(pages));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual Reactor batch original64 items/copy4096/cap65536: body={length},loans8,turns={turns},widest={widest},same recipient exact heap,source close before wire delivery,terminalDrop0");}}

/// 🛑️ Every portable prefix keeps all original producer addresses and closes every partial destination before producer retirement.
#[test]
fn native_page_batch_cancellation_preserves_original_source_and_partial_destination_custody(){let g=original();for row in fixture()["pageLengths"].as_array().unwrap(){let length=row.as_u64().unwrap()as usize;for cut in fixture()["cancellationPrefixes"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let(mut pages,mut producers)=prepared(length);let pointers:Vec<_>=producers.iter().map(|page|page.bytes().as_ptr()).collect();for _ in 0..cut{for slot in &mut pages.slots{let(p,heap)=observe(||slot.advance(g).unwrap());receipt(p,heap,g);}}for(slot,pointer)in producers.iter().zip(&pointers){assert_eq!(slot.bytes().as_ptr(),*pointer);}close_pages(&mut pages,g);close_producers(&mut producers,g);let(_,heap)=observe(||drop(pages));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual Reactor batch cancellation body={length} prefix={cut}:8 original loans,partial wires and aliases physically closed,terminalDrop0");}}}

/// 🧳️ A born destination remains in its original receiving slot until the caller accepts and exposes it.
#[test]
fn native_page_publication_cancel_after_birth_keeps_destination_before_ack(){let g=original();let(mut pages,mut producers)=prepared(4096);for slot in &mut pages.slots{for _ in 0..100{if slot.ready(){break}let(p,heap)=observe(||slot.advance(g).unwrap());receipt(p,heap,g);}assert!(slot.ready());}let mut effects=Vec::new();let mut sequence=0;let mut progress=RetainedCloneProgress::default();let cx=semio_framework_job::StepContext::new(semio_framework_job::OperationId(7),semio_framework_job::Generation(1),semio_framework_job::StepBudget::new(100,u64::MAX,g),semio_framework_job::CancelToken::root_now(),semio_framework_job::logical_now_us,&mut sequence,&mut progress);let((born,p),heap)=observe(||publish(&mut pages.slots[0],7,&mut effects,64,&cx).unwrap());receipt(p,heap,g);assert!(born);assert!(effects.is_empty());assert!(pages.slots[0].receiver.is_none());let Effect::SendMessage{payload,..}=pages.slots[0].publication.as_ref().unwrap()else{panic!("original destination missing")};assert_eq!(payload.len(),TypedOperationResultPage::RENDERER_PAGE_MAGIC.len()+30+4096);let pointer=payload.as_ptr();assert!(!pages.terminal_is_empty());close_pages(&mut pages,g);close_producers(&mut producers,g);retire_effects(effects,g);let(_,heap)=observe(||drop(pages));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] actual born renderer destination {pointer:p} retained in original slot before receipt/handoff; cancellation closes payload,target,original loans and empty output capacity,terminalDrop0");}
